if(!Array.isArray(entries)||!entries.length||entries.some(e=>!e||!DB.profiles.some(p=>p.id===e.id)||!Number.isFinite(e.score))||new Set(entries.map(e=>e.id)).size!==entries.length)throw Error('Match results require distinct existing players and finite scores.');
